<?php require __DIR__.'/inc/bootstrap.php'; $posts=load_json('posts.json'); $id=$_GET['id']??''; $post=null; foreach($posts as $p){if((string)$p['id']===(string)$id){$post=$p;break;}} ?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($post['title']??'DATA NOT FOUND') ?></title><link rel="stylesheet" href="assets/style.css"></head><body><?php include __DIR__.'/inc/header.php'; ?><main class="container"><article class="card"><?php if($post): ?><div class="post-meta">[ DATA LOG ] <?= e($post['date']??'') ?></div><h1><?= e($post['title']) ?></h1><div style="white-space:pre-wrap;line-height:1.8"><?= e($post['content']) ?></div><?php else: ?><h1>DATA NOT FOUND</h1><?php endif; ?></article></main><?php include __DIR__.'/inc/footer.php'; ?></body></html>
